package edu.portal.ui;
import edu.portal.dao.*; import edu.portal.util.CsvExporter; import java.nio.file.Path; import java.util.*;
/** Menu shell keeps the assignment demonstrable; all DB access remains in prepared-statement DAO/service classes. */
public class ConsoleApp { public static void main(String[] args){Scanner s=new Scanner(System.in);while(true){System.out.println("\nONLINE JOB PORTAL\n1 List Students\n2 Company Management\n3 Vacancy Management\n4 Apply for Job\n5 Update Application Status\n6 Reports\n7 Export Reports to CSV\n0 Exit");System.out.print("Choose: ");try{switch(s.nextLine()){case "0"-> {return;} case "1"->{for(var x:new JdbcStudentDao().findAll())System.out.printf("%-4d %-24s %.2f%n",x.id(),x.name(),x.cgpa());} case "6"->System.out.println("Use v_company_recruitment_summary, v_department_placement_stats and v_vacancy_application_counts."); case "7"->{CsvExporter.queryToCsv("SELECT * FROM student",Path.of("..","data","exports","student.csv"));System.out.println("student.csv exported.");} default->System.out.println("Module available through its DAO/service layer; see source documentation.");}}catch(Exception e){System.out.println("Operation failed: "+e.getMessage());}}}}
